function drawHook(){let x1=hero.x,y1=hero.y-8,x2=hook.x,y2=hook.y;ctx.save();ctx.shadowColor='#c498ff';ctx.shadowBlur=9;ctx.strokeStyle='#d5b9ff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x1,y1);ctx.quadraticCurveTo((x1+x2)/2,(y1+y2)/2-12,x2,y2);ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#eadbff';ctx.beginPath();ctx.arc(x2,y2,4,0,Math.PI*2);ctx.fill();ctx.restore()}
function spawnEnemy(boss=false){const angle=rand(0,Math.PI*2),rx=Math.min(w*.37,250),ry=Math.min(h*.28,150);let x=w*.5+Math.cos(angle)*rx,y=h*.58+Math.sin(angle)*ry;if(w<500){x=w*.5+Math.cos(angle)*w*.36;y=h*.57+Math.sin(angle)*h*.25}const s=scene(),factor=1+(data.zone-1)*.35+(data.tower-1)*.2;let hp=Math.round((boss?100:30+Math.random()*14)*factor);const colors=['#b275f2','#e67f9c','#7ca8ed','#77dab7','#e7aa65'];const color=colors[Math.floor(Math.random()*colors.length)];enemies.push({id:++enemyId,x,y,hp,maxHp:hp,damage:(boss?12:5+data.zone)*factor,scale:boss?1.55:rand(.8,1.08),color,dark:boss?'#322138':'#26243a',phase:Math.random()*9,flash:0,boss,pull:0,attackTimer:rand(1.5,3.8),speed:boss?18:rand(20,33),dead:false});if(boss){toast('✦  A HOLLOW GUARDIAN HAS AWAKENED  ✦');$('waveText').innerHTML='BOSS <span style="color:#89839c">◆</span>'}}
function nearest(){if(targetId){let marked=enemies.find(e=>e.id===targetId);if(marked&&!marked.dead)return marked}return enemies.filter(e=>!e.dead).sort((a,b)=>Math.hypot(a.x-hero.x,a.y-hero.y)-Math.hypot(b.x-hero.x,b.y-hero.y))[0]}
function startHook(){let e=nearest();if(!e||hook)return;if(targetId&&e.id!==targetId)targetId=e.id;hook={enemy:e.id,x:e.x,y:e.y,state:'out',speed:590,damage:data.attack}}
function addXP(n){data.xp+=n;while(data.xp>=data.level*20){data.xp-=data.level*20;data.level++;data.health+=8;hero.hp=Math.min(data.health,hero.hp+30);toast('✦ SOUL RESONANCE · LEVEL '+String(data.level).padStart(2,'0')+' ✦');burst(hero.x,hero.y,'#c49aff',18)}}
function devour(e){if(e.dead)return;e.dead=true;hook=null;data.souls+=e.boss?8:1;let coins=e.boss?18:3+Math.floor(Math.random()*3);data.coins+=coins;runCoins+=coins;data.kills++;runKills++;addXP(e.boss?16:6);burst(e.x,e.y,e.color,e.boss?30:14);floatText(e.x,e.y-16,e.boss?'+8 ✦  GUARDIAN DEVOURED':'+1 ✦  DEVOUR',e.boss?'#ffd27e':'#d7baff',11);floatText(e.x+18,e.y+3,'+'+coins+' ◈','#ffd477',10);if(e.boss){data.tower++;data.gear=Math.min(3,data.gear+1);data.coins+=12;runCoins+=12;toast('GUARDIAN SLAIN · RELIC FOUND');if(mode==='hunt'){data.zone++;data.kills=0;runKills=0;setTimeout(()=>{if(!paused){updateSceneUI();toast('ENTERING '+scene().name.toUpperCase())}},1200)}}if(targetId===e.id)targetId=null;updateUI();save()}
function burst(x,y,color,n){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,v=rand(25,150);particles.push({type:'spark',x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.35,.8),max:.8,r:rand(1.2,3.5),color})}}
function floatText(x,y,text,color,size=12){floating.push({x,y,text,color,size,life:1.3})}
function toast(text){const t=$('toast');t.textContent=text;t.classList.add('show');toastTimer=2.2}
function update(dt){if(paused)return;elapsed+=dt;spawnTimer-=dt;hookTimer-=dt;hitFlash=Math.max(0,hitFlash-dt);if(hero.invuln>0)hero.invuln-=dt;if(spawnTimer<=0){let boss=(mode==='tower'?data.tower:data.kills?Math.floor(data.kills/5):0)>0&&(mode==='tower'?runKills%5===4:runKills%5===4);spawnEnemy(boss);spawnTimer=rand(2,3.8)/Math.min(1.6,data.speed)}if(auto&&hookTimer<=0&&!hook){startHook();hookTimer=1.35/data.speed}
for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];if(e.dead){enemies.splice(i,1);continue}if(e.flash>0)e.flash-=dt;let dx=hero.x-e.x,dy=hero.y-e.y,d=Math.hypot(dx,dy)||1;if(e.pull>0){e.pull-=dt;e.x+=dx/d*Math.min(d,e.speed*2.7*dt);e.y+=dy/d*Math.min(d,e.speed*2.7*dt);if(d<28){e.hp-=data.attack;if(e.hp<=0){devour(e);continue}e.pull=0;floatText(e.x,e.y-25,'✧ '+Math.round(data.attack), '#ffcf87');hero.invuln=Math.max(hero.invuln,.2)}}else if(d>42){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*.7*dt}else{e.attackTimer-=dt;if(e.attackTimer<=0&&hero.invuln<=0){let dmg=Math.max(1,e.damage*(1-data.armor/100));hero.hp-=dmg;hero.invuln=.48;e.attackTimer=rand(1.5,2.4);floatText(hero.x,hero.y-30,'-'+Math.round(dmg),'#ff8199');if(hero.hp<=0){hero.hp=0;gameOver=true;showGameOver()}}}}
if(hook){let e=enemies.find(q=>q.id===hook.enemy);if(!e||e.dead)hook=null;else{let dx=e.x-hook.x,dy=e.y-hook.y,d=Math.hypot(dx,dy)||1;hook.x+=dx/d*hook.speed*dt;hook.y+=dy/d*hook.speed*dt;if(d<18){e.hp-=hook.damage;e.flash=.14;e.pull=3.2;hook=null;floatText(e.x,e.y-25,'✧ '+Math.round(data.attack),'#e8caff');burst(e.x,e.y,e.color,6)}}}
for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.97;p.vy*=.97;p.life-=dt;if(p.life<=0)particles.splice(i,1)}for(let i=floating.length-1;i>=0;i--){let f=floating[i];f.y-=24*dt;f.life-=dt;if(f.life<=0)floating.splice(i,1)}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}
}
function frame(t){let dt=Math.min(.04,(t-lastTime)/1000||0);lastTime=t;update(dt);draw();requestAnimationFrame(frame)}
function updateUI(){const xpNeed=data.level*20;$('soulTop').textContent=data.souls;$('coinTop').textContent=data.coins;$('soulCount').textContent='✦ '+data.souls;$('heroLevel').textContent='LV '+String(data.level).padStart(2,'0');$('levelBadge').textContent='LV '+String(data.level).padStart(2,'0');$('hpText').textContent=Math.ceil(hero.hp)+' / '+data.health;$('hpBar').style.width=Math.max(0,hero.hp/data.health*100)+'%';$('xpBar').style.width=data.xp/xpNeed*100+'%';$('profileXpBar').style.width=data.xp/xpNeed*100+'%';$('xpLabel').textContent=data.xp+' / '+xpNeed;$('attackVal').innerHTML=data.attack+' <span class="delta">+'+(data.attack-12)+'</span>';$('healthVal').innerHTML=data.health+' <span class="delta">+'+(data.health-100)+'</span>';$('speedVal').textContent=data.speed.toFixed(1)+'x';$('armorVal').textContent=data.armor+'%';$('killText').textContent=runKills;$('runCoin').textContent=runCoins;$('costAttack').textContent=cost('attack');$('costHealth').textContent=cost('health');$('costSpeed').textContent=cost('speed');$('costArmor').textContent=cost('armor');document.querySelectorAll('.upgrade').forEach(b=>b.disabled=data.souls<cost(b.dataset.up));$('autoBtn').innerHTML=auto?'Ⅱ &nbsp;AUTO HUNT':'▶ &nbsp;AUTO HUNT';$('soundBtn').style.color=data.sound?'#d2c3ff':'#777'}
function cost(stat){let base={attack:5,health:5,speed:8,armor:10}[stat],level=data.upgrades[stat];return Math.floor(base*Math.pow(1.65,level))}
function buy(stat){let c=cost(stat);if(data.souls<c){toast('NOT ENOUGH SOULS · DEVOUR MORE FOES');return}data.souls-=c;data.upgrades[stat]++;if(stat==='attack')data.attack+=3;if(stat==='health'){data.health+=25;hero.hp+=25}if(stat==='speed')data.speed+=.15;if(stat==='armor')data.armor=Math.min(70,data.armor+5);floatText(w*.5,h*.45,'SOUL TREE · AWAKENED','#d2baff',13);updateUI();save()}
function updateSceneUI(){$('zoneName').textContent=scene().name.toUpperCase()+' · ZONE '+String(data.zone).padStart(2,'0');$('sceneTitle').textContent=scene().name;$('sceneSubtitle').textContent=scene().subtitle;$('sceneEyebrow').textContent=scene().eyebrow;$('waveText').innerHTML=String((runKills%5)+1).padStart(2,'0')+' <span style="color:#89839c">/ 05</span>';seedDecor()}

