function updateSceneUI(){$('zoneName').textContent=scene().name.toUpperCase()+' · ZONE '+String(data.zone).padStart(2,'0');$('sceneTitle').textContent=scene().name;$('sceneSubtitle').textContent=scene().subtitle;$('sceneEyebrow').textContent=scene().eyebrow;$('waveText').innerHTML=String((runKills%5)+1).padStart(2,'0')+' <span style="color:#89839c">/ 05</span>';seedDecor()}
function openModal(kind){modalKind=kind;paused=true;const m=$('modal');let head=(title,desc)=>`<div class="modal-head"><div><div class="overline">SOULBOUND · ${kind.toUpperCase()}</div><h2>${title}</h2></div><button class="close" id="closeModal">×</button></div><p>${desc}</p>`;if(kind==='tree'){m.innerHTML=head('The Soul Tree','Every soul you devour leaves a permanent mark. Choose how your Wraith evolves.')+`<div class="tree-list">${[['attack','✧','Ravenous Hunger','+3 hook damage per rank'],['health','♡','Hollow Heart','+25 maximum health per rank'],['speed','➶','Phantom Step','+15% hook speed per rank'],['armor','◈','Umbral Guard','+5% damage reduction per rank']].map(([key,glyph,name,desc])=>`<div class="tree-node"><div class="node-glyph">${glyph}</div><div><b>${name}</b><small>${desc} · RANK ${data.upgrades[key]}</small></div><button data-modal-up="${key}" ${data.souls<cost(key)?'disabled':''}>✦ ${cost(key)}</button></div>`).join('')}</div><button class="modal-action" id="modalDone">RETURN TO THE HUNT</button>`}else if(kind==='tower'){m.innerHTML=head('Boss Tower','A test of endurance. Every fifth devour summons a Guardian. Defeat it to climb higher and claim a relic.')+`<div class="offline"><b>FLOOR ${String(data.tower).padStart(2,'0')}</b><br><span style="font-size:11px;color:#a49bb8">Guardian bounty: 8 souls · 30 shards</span></div><button class="modal-action" id="enterTower">${mode==='tower'?'RETURN TO CAMPAIGN':'ENTER THE TOWER'}</button>`}else if(kind==='gear'){m.innerHTML=head('Relic Vault','Trade your gathered shards for a mystery relic. Relics strengthen every run; your first Moon Shard grants +10% attack.')+`<div class="tree-node"><div class="node-glyph">🌙</div><div><b>Moon Shard ${data.gear?'· Owned':'· Starter relic'}</b><small>+10% hook damage · ${Math.max(0,4-data.gear)} vault slots available</small></div><span style="color:#b6a4e7">${data.gear?'✓':'EQUIPPED'}</span></div><div class="tree-node"><div class="node-glyph">🎁</div><div><b>Sealed Soul Chest</b><small>Contains 3–6 souls and 15–30 shards</small></div><button id="chestBtn" ${data.coins<30?'disabled':''}>◈ 30</button></div><button class="modal-action" id="modalDone">RETURN TO THE HUNT</button>`}else if(kind==='gameover'){m.innerHTML=head('Your light fades…','The dark has claimed this hunt, but your souls and permanent upgrades remain yours. Regroup and return stronger.')+`<div class="offline"><b>HUNT SUMMARY</b><br><span style="font-size:11px;color:#b8accd">${runKills} foes devoured · ${runCoins} shards gathered · Floor ${data.tower}</span></div><button class="modal-action" id="reviveBtn">RISE AGAIN · RESTORE TO FULL</button>`}else{m.innerHTML=head('The Hollow Wilds','The forest is quiet for now.')+'<button class="modal-action" id="modalDone">RETURN TO THE HUNT</button>'} $('overlay').classList.add('open');$('closeModal').onclick=closeModal;let done=$('modalDone');if(done)done.onclick=closeModal;m.querySelectorAll('[data-modal-up]').forEach(b=>b.onclick=()=>{buy(b.dataset.modalUp);openModal('tree')});let enter=$('enterTower');if(enter)enter.onclick=()=>{mode=mode==='tower'?'hunt':'tower';runKills=0;runCoins=0;updateSceneUI();closeModal();toast(mode==='tower'?'BOSS TOWER · ENDLESS ASCENT':'CAMPAIGN · GLOAMWOOD')};let chest=$('chestBtn');if(chest)chest.onclick=()=>{if(data.coins<30)return;data.coins-=30;let souls=3+Math.floor(Math.random()*4),coins=15+Math.floor(Math.random()*16);data.souls+=souls;data.coins+=coins;toast('CHEST OPENED · +'+souls+' ✦  +'+coins+' ◈');updateUI();save();openModal('gear')};let revive=$('reviveBtn');if(revive)revive.onclick=()=>{hero.hp=data.health;gameOver=false;runKills=0;runCoins=0;enemies=[];hook=null;closeModal();updateUI();toast('THE WRAITH RISES AGAIN')};}
