+function update(dt){if(paused)return;elapsed+=dt;spawnTimer-=dt;hookTimer-=dt;hitFlash=Math.max(0,hitFlash-dt);if(hero.invuln>0)hero.invuln-=dt;if(spawnTimer<=0){let boss=runKills>0&&runKills%5===4;spawnEnemy(boss);spawnTimer=rand(2,3.8)/Math.min(1.6,data.speed)}if(auto&&hookTimer<=0&&!hook){startHook();hookTimer=1.35/data.speed}
